// Two nudges for Claude, with no model calls of their own, ported from cablate/ctx-handoff-mod (MIT):
// the same failure or refusal twice in a row, and "done" with no check since the last edit.
// A nudge is text only the model reads; the person sees a line in the transcript when a stop is sent back.
import type { Register, ToolCallResult } from 'claude-code'

import { doneCheck, freshWork, noteCall, outcomeOf, trackOutcome } from './lib/checks.ts'
import type { Streak } from './lib/checks.ts'

// Module state: a reload starts both over, which costs at most one nudge.
const streaks = new Map<string, Streak>()
let work = freshWork()

export const register: Register = (on, options) => {
  const opts = (options ?? {}) as Record<string, unknown>
  const isFailureOn = opts.repeatedFailure !== 'off'
  const isDoneOn = opts.doneCheck !== 'off'

  // After every tool call: note this turn's edits and checks, and add a nudge to the second same failure.
  // Never throws and never changes whether the call ran: on any error of its own the result goes through as is.
  on('tool.call', async ($, e, next) => {
    const r = await next(e)
    try {
      const scope = (e as { agentId?: string }).agentId ?? ''
      const isDeny = r.deny !== undefined
      const isError = r.isError === true
      // Subagents' edits and checks are theirs, not the main conversation's turn.
      if (isDoneOn && scope === '' && !isDeny) noteCall(work, e.tool, e as Record<string, unknown>, isError)
      if (!isFailureOn) return r
      const text = r.deny ?? r.text ?? (typeof r.result === 'string' ? r.result : undefined)
      const nudge = trackOutcome(streaks, scope, e.tool, outcomeOf(isError, isDeny, text), text)
      if (!nudge) return r
      // A deny carries no context, so the nudge rides in its text.
      if (r.deny !== undefined) return { deny: `${r.deny}\n\n${nudge}` }
      return { ...r, context: [...(r.context ?? []), nudge] } as ToolCallResult
    } catch {
      return r
    }
  }).catch(($, e, next) => next(e))
  // Each .catch here lets the call through untouched: `next(e)` replays what the hook's own call
  // settled to, so nothing runs twice. A nudge never stands in the way.

  // Claude is about to stop: if it says it's done but nothing checked its last code edit, send it back once.
  on('classic.Stop', async ($, e, next) => {
    const out = await next(e)
    // Another Stop hook already sent the turn back: decide at the stop that really ends it.
    if (out.block !== undefined) return out
    if ((e as { agent_id?: string }).agent_id !== undefined) return out
    try {
      const reason = isDoneOn ? doneCheck(work, e.last_assistant_message, e.stop_hook_active === true) : undefined
      if (reason) {
        $.ui.log('nudges: Claude said done with no check since its last edit, so it was asked to check first')
        return { ...out, block: reason }
      }
    } catch {}
    work = freshWork()
    return out
  }).catch(($, e, next) => next(e))

  // A message from the person starts a new turn, and may have changed what fails or what is allowed.
  on('prompt.submit', async ($, e, next) => {
    if (e.origin.kind === 'composer' || e.origin.kind === 'bridge') {
      work = freshWork()
      streaks.clear()
    }
    return next(e)
  }).catch(($, e, next) => next(e))

  // An interrupted turn has no Stop: drop its record so it isn't counted into the next one.
  on('turn.complete', async ($, e, next) => {
    if (e.agentId === undefined && e.isAborted) work = freshWork()
    return next(e)
  })
}

