// The two nudges' logic, kept apart from `$`: the same failure or refusal twice in a row,
// and "done" with no check since the last edit. Ported from cablate/ctx-handoff-mod's loops.ts (MIT).
// Their state is module state: a reload clears it, which only costs one nudge.

export const TAG = '[nudges]'

// --- A: the same failure, or the same refusal, twice in a row ---

export type Streak = { sig: string; count: number; isNudged: boolean }

const MAX_SIG = 200
const MAX_STREAKS = 200
// Built with the constructor so no control character sits in the pattern.
const ANSI = new RegExp(String.raw`${String.fromCharCode(27)}\[[0-9;]*[A-Za-z]`, 'g')

// The person stopped or rejected the call: not a failure, and nothing to say about it.
const USER_STOP = /doesn't want to proceed|user rejected|tool use was rejected|interrupted by user|request interrupted|user denied/i
// A permission rule, the auto-mode classifier or a guard refused the call: retrying it, or getting the
// same result another way, is the wrong move, so these get their own nudge.
const REFUSAL =
  /has been denied|denied by your permission settings|denied by the Claude Code auto mode classifier|permission (?:for|to) [^.\n]{0,80}denied|\bblocked, because\b/i

export type Outcome = 'ok' | 'stopped' | 'failed' | 'refused'

export const outcomeOf = (isError: boolean, isDeny: boolean, text: string | undefined): Outcome => {
  if (isDeny) return 'refused'
  if (!isError) return 'ok'
  if (USER_STOP.test(text ?? '')) return 'stopped'
  return REFUSAL.test(text ?? '') ? 'refused' : 'failed'
}

// An error's signature: colour codes, paths, numbers (lines, times, ids) and spacing removed.
export const failureSignature = (text: string | undefined): string =>
  (text ?? '')
    .replace(ANSI, '')
    .replace(/<\/?tool_use_error>/g, '')
    .replace(/[A-Za-z]:[\\/][^\s'"`)>\]]*/g, '<p>')
    .replace(/(?:\.{0,2}\/)?(?:[\w.@~-]+\/)+[\w.@~-]*/g, '<p>')
    .replace(/\d+/g, '#')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, MAX_SIG)

// A refusal of `conda` in Bash and then in PowerShell is the same refusal: the shell's name is dropped.
const refusalSignature = (text: string | undefined) => failureSignature((text ?? '').replace(/\b(?:Bash|PowerShell)\b/g, '<shell>'))

// The first non-empty line, cut to 80 characters, for the model to recognise.
const brief = (text: string | undefined) => {
  const line = (text ?? '').replace(/<\/?tool_use_error>/g, '').split('\n').map(l => l.trim()).find(Boolean) ?? ''
  return line.length > 80 ? `${line.slice(0, 80)}…` : line
}

export const failureNudge = (tool: string, text: string | undefined) =>
  `${TAG} ${tool} failed twice in a row for the same reason (${brief(text) || 'no error text'}). ` +
  'If the error looks temporary (a timeout, something still loading, a dropped connection), wait and retry once. ' +
  'Otherwise find the cause and change approach instead of retrying as is; before calling it a dead end, run /unstuck.'

export const refusalNudge = (text: string | undefined) =>
  `${TAG} The same thing was refused twice (${brief(text) || 'no reason given'}). ` +
  "A refusal by a permission rule, the auto-mode classifier or a guard isn't a bug to fix: don't retry it, " +
  "and don't reach the same result another way. If the step is still needed, stop and ask the user, or give them a one-line `!` command to run themselves."

// Notes one finished tool call; on the second failure (or refusal) in a row with the same signature,
// returns the nudge to hand the model. Once per streak. A success clears that tool's failure streak.
export function trackOutcome(
  streaks: Map<string, Streak>, scope: string, tool: string, outcome: Outcome, text: string | undefined,
): string | undefined {
  const key = outcome === 'refused' ? `${scope}|refused` : `${scope}|${tool}`
  if (outcome === 'ok' || outcome === 'stopped') {
    streaks.delete(key)
    return undefined
  }
  const sig = outcome === 'refused' ? refusalSignature(text) : failureSignature(text)
  const prev = streaks.get(key)
  if (!prev || prev.sig !== sig) {
    // A new signature starts a new streak; the cap only stops the map growing without end.
    if (!prev && streaks.size >= MAX_STREAKS) streaks.clear()
    streaks.set(key, { sig, count: 1, isNudged: false })
    return undefined
  }
  prev.count += 1
  if (prev.isNudged) return undefined
  prev.isNudged = true
  return outcome === 'refused' ? refusalNudge(text) : failureNudge(tool, text)
}

// --- B: "done", with no check since the last edit ---

// This turn's work. seq counts finished tool calls; lastEdit and lastCheck are the seq of the last
// code edit and the last passing check (0 = none); isCheckFailed, whether the last check failed.
export type Work = { seq: number; lastEdit: number; lastCheck: number; isCheckFailed: boolean; isReminded: boolean }
export const freshWork = (): Work => ({ seq: 0, lastEdit: 0, lastCheck: 0, isCheckFailed: false, isReminded: false })

const EDIT_TOOLS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit'])
// Prose, license and git housekeeping files, and scratch files, need no test run.
const DOC_FILE = /(?:\.(?:md|mdx|txt|rst|adoc)|(?:^|[\\/])(?:LICENSE|NOTICE|COPYING|\.gitignore|\.gitattributes|\.editorconfig))$/i
const SCRATCH_PATH = /(?:^|[\\/])scratchpad[\\/]/i
// Commands that only look at or move things, whatever words follow them.
const NOT_RUNNING = new Set([
  'ls', 'cat', 'echo', 'grep', 'rg', 'find', 'head', 'tail', 'git', 'gh', 'cd', 'mkdir', 'rm', 'cp', 'mv', 'sed', 'awk',
  'type', 'wc', 'diff', 'open', 'pwd', 'which', 'printf', 'code', 'start', 'explorer', 'robocopy',
  'get-content', 'gc', 'select-string', 'sls', 'get-childitem', 'gci', 'dir', 'set-location', 'sl', 'test-path',
  'write-output', 'write-host', 'copy-item', 'move-item', 'remove-item', 'new-item', 'get-item', 'set-content',
])
// What a check says it does: tests, type checks, linters, builds, validators, parse checks, LaTeX and
// Quarto builds, {targets} runs. An underscore separates words here, so 00d_validate_data.R counts.
const CHECK_WORDS =
  /(?<![A-Za-z0-9])(tests?|pytest|unittest|testthat|jest|vitest|mocha|tsc|typecheck|lint|eslint|biome|ruff|mypy|pyright|flake8|clippy|check|build|compile|py_compile|parse|verify|verification|validate|vet|latexmk|pdflatex|xelatex|lualatex|quarto|render|knit|tar_make)(?![A-Za-z0-9])/i

// The program a command segment starts: past PowerShell's `&`, quotes, folders and `.exe`.
const programOf = (segment: string) => {
  const words = segment.trim().split(/\s+/)
  const first = words[0] === '&' ? words[1] : words[0]
  return (first ?? '').replace(/^["']|["']$/g, '').replace(/^.*[\\/]/, '').replace(/\.exe$/i, '').toLowerCase()
}

// Whether a Bash or PowerShell command looks like a test, check or build (any one segment will do).
export const isCheckCommand = (command: string | undefined) =>
  (command ?? '').split(/&&|\|\||;|\||\n/).some(segment => {
    const program = programOf(segment)
    return program !== '' && !NOT_RUNNING.has(program) && CHECK_WORDS.test(segment)
  })

type CallInput = Record<string, unknown>

// Notes one finished tool call of the main conversation. A failed edit isn't an edit; a failed check
// marks the work unchecked rather than checked.
export function noteCall(work: Work, tool: string, input: CallInput, isFailed: boolean) {
  work.seq += 1
  if (EDIT_TOOLS.has(tool)) {
    if (isFailed) return
    const file = [input.file_path, input.notebook_path, input.path].find((p): p is string => typeof p === 'string')
    if (file && (DOC_FILE.test(file) || SCRATCH_PATH.test(file))) return
    work.lastEdit = work.seq
    work.isCheckFailed = false
    return
  }
  const isCheck =
    ((tool === 'Bash' || tool === 'PowerShell') && typeof input.command === 'string' && isCheckCommand(input.command)) ||
    (tool === 'Skill' && input.skill === 'verify')
  if (!isCheck) return
  if (isFailed) {
    work.isCheckFailed = true
  } else {
    work.lastCheck = work.seq
    work.isCheckFailed = false
  }
}

// Saying it's done: only the start and end of the reply are read, and questions don't count.
const CLAIM =
  /\b(all done|all set|i(?:'ve| have) (?:finished|completed|fixed)|(?:is|are|now|it's|that's) (?:done|fixed|complete(?:d)?|finished)|fixed it|works now|now works|should (?:now )?work|everything (?:is )?(?:done|working|fixed|in place))\b/i
// "Done." or "Fixed:" opening a line.
const CLAIM_OPENING = /(?:^|\n)\W{0,3}(?:done|fixed)\b(?!-)/i
// Already says what wasn't checked, or that a check failed: no nudge.
const HONEST =
  /\b(?:not (?:yet )?(?:been )?(?:tested|verified|checked|run)|untested|unverified|couldn't (?:run|verify|test|check)|could not (?:run|verify|test|check)|unable to (?:run|verify|test|check)|haven't (?:run|tested|verified|checked)|didn't (?:run|test|verify|check)|did not (?:run|test|verify|check)|(?:tests?|checks?|build|validation) (?:failed|fails)|failing tests?)\b/i

export function claimsDone(message: string | undefined) {
  const text = (message ?? '').trim()
  if (!text || /\?$/.test(text)) return false
  const ends = text.length <= 600 ? text : `${text.slice(0, 200)}\n${text.slice(-400)}`
  return (CLAIM.test(ends) || CLAIM_OPENING.test(ends)) && !HONEST.test(ends)
}

export const doneNudge = (isCheckFailed: boolean) =>
  isCheckFailed
    ? `${TAG} You said it's done, but the last test or check after your edits this turn failed. ` +
      'Fix it and run the check again, then report what ran and the result; ' +
      "if you can't fix it or it's unrelated to this change, say so plainly instead of calling it done."
    : `${TAG} You said it's done, but no test or check has run since your last code edit this turn. ` +
      'Run the check that fits the change (tests, a build, a validator, a parse check, or the changed script itself) ' +
      'and report what ran and the result; where nothing can check it, say what is unverified and why instead of calling it done.'

// At a stop: the reason to send Claude back, once per turn. isStopHookActive means a Stop hook
// already sent this turn back once.
export function doneCheck(work: Work, message: string | undefined, isStopHookActive: boolean): string | undefined {
  if (work.isReminded || isStopHookActive) return undefined
  if (work.lastEdit === 0 || (work.lastCheck > work.lastEdit && !work.isCheckFailed)) return undefined
  if (!claimsDone(message)) return undefined
  work.isReminded = true
  return doneNudge(work.isCheckFailed)
}

