{
  "name": "nudges",
  "version": "0.1.0",
  "description": "Two one-line nudges to Claude, with no model calls: when the same failure or refusal happens twice, and when it says done with no check since its last edit.",
  "author": {
    "name": "daldaman",
    "url": "https://github.com/daldaman"
  },
  "license": "MIT",
  "userConfig": {
    "repeatedFailure": {
      "type": "string",
      "title": "Repeated failure nudge",
      "options": [
        "on",
        "off"
      ],
      "default": "on",
      "description": "When a tool fails twice in a row for the same reason, or the same thing is refused twice, Claude is told to change approach (or, for a refusal, to ask you) instead of retrying."
    },
    "doneCheck": {
      "type": "string",
      "title": "Done-without-a-check nudge",
      "options": [
        "on",
        "off"
      ],
      "default": "on",
      "description": "When Claude says the work is done but no test or check ran after its last code edit this turn, it is sent back once to run one or to say what is unverified."
    }
  }
}
